export const CUSTOMER_BY_CODE = new Map<string, CustomerInfo>(
  CUSTOMER_LIST.map((c) => [c.code, c])
);

const ALIAS_MAP = new Map<string, CustomerInfo>();
for (const c of CUSTOMER_LIST) {
  for (const a of c.aliases) {
    const key = a.trim().toLowerCase();
    if (!ALIAS_MAP.has(key)) ALIAS_MAP.set(key, c);
    const keyTrimmed = key.replace(/[\s.,*]+$/, '');
    if (!ALIAS_MAP.has(keyTrimmed)) ALIAS_MAP.set(keyTrimmed, c);
  }
}

export function findCustomerByAlias(alias: string): CustomerInfo | undefined {
  const raw = alias.trim().toLowerCase();
  const direct = ALIAS_MAP.get(raw);
  if (direct) return direct;
  return ALIAS_MAP.get(raw.replace(/[\s.,*]+$/, ''));
}

